function academy(){return `<section class="pagehero academy-hero"><div class="container"><span class="eyebrow">JUMI TECH ACADEMY</span><h1>Learn. Build. Create. Grow.</h1><p>Live online technology training built around practical skills, clear learning pathways and weekly topics. Review the course details before you register.</p><div class="actions"><a class="btn primary" href="/academy/register">Register for a course →</a><a class="btn" target="_blank" rel="noopener" href="https://chat.whatsapp.com/IGrK6qwLDm2JhiGaG1MO0I?s=cl&p=a&mlu=4&ilr=4">Join the learning community</a></div></div></section><section class="section"><div class="container"><div class="sectionhead"><div><span class="eyebrow">Current courses</span><h2>Choose your learning path.</h2></div><p>Each course runs for three months with live online classes three times per week. Tuition is shown clearly below.</p></div><div class="grid academy-course-grid">${Object.entries(academyCourses).map(([slug,c])=>`<article class="card reveal"><div class="icon">${slug==='ethical'?'04':slug==='python'?'03':slug==='backend'?'02':'01'}</div><h3>${c.name}</h3><p>${c.summary}</p><div class="course-meta"><strong>₦${c.fee.toLocaleString('en-NG')}</strong><span>3 months · Live online</span><span>${c.schedule}</span></div><a class="btn" href="/academy/course/${slug==='ethical'?'ethical-hacking':slug}">View syllabus →</a></article>`).join('')}</div></div></section><section class="section"><div class="container feature"><div class="card reveal"><span class="eyebrow">Flexible enrollment</span><h2 style="font:700 36px 'Space Grotesk'">Ready to get started?</h2><p>Register and pay in full, choose the proposed 50/50 installment plan, or join the waitlist without paying yet.</p><a class="btn primary" href="/academy/register">Start registration →</a></div><div class="card reveal"><span class="eyebrow">Need to ask something?</span><h2 style="font:700 36px 'Space Grotesk'">Talk to Jumi Tech.</h2><p>For questions about course availability, payment arrangements or class start dates, contact the Academy team.</p><a class="btn" target="_blank" rel="noopener" href="https://wa.me/2347042536745?text=Hello%20Jumi%20Tech%2C%20I%20have%20a%20question%20about%20Jumi%20Tech%20Academy.">Ask on WhatsApp →</a></div></div></section>`}
function academyCourse(slug){const c=academyCourses[slug];if(!c)return `<section class="pagehero"><div class="container"><h1>Course not found</h1><a class="btn" href="/academy">Back to Academy</a></div></section>`;return `<section class="pagehero"><div class="container"><span class="eyebrow">JUMI TECH ACADEMY · 3-MONTH COURSE</span><h1>${c.name}</h1><p>${c.summary}</p><div class="actions"><a class="btn primary" href="/academy/register?course=${encodeURIComponent(c.name)}">Register for this course →</a><a class="btn" href="/academy">All courses</a></div></div></section><section class="section"><div class="container"><div class="course-summary-grid"><article class="card"><span class="eyebrow">Tuition</span><h2>₦${c.fee.toLocaleString('en-NG')}</h2><p>Full payment or two installments of 50% each.</p></article><article class="card"><span class="eyebrow">Timetable</span><h2>${c.schedule}</h2><p>Two hours per class · Three classes per week · 72 live training hours across 12 weeks.</p></article><article class="card"><span class="eyebrow">Requirements</span><p>${c.requirements}</p></article></div><div class="card syllabus-card"><span class="eyebrow">Student syllabus</span><h2>What you will learn</h2><p class="muted-copy">The syllabus is organised by week. The final week of each month is reserved for practical application.</p>${c.months.map((month,i)=>`<section class="syllabus-month"><h3>Month ${i+1}</h3>${month.map((topics,j)=>`<div class="syllabus-week"><strong>Week ${i*4+j+1}</strong><div>${topics.length===1?`<p>${topics[0]}</p>`: `<ul>${topics.map(t=>`<li>${t}</li>`).join('')}</ul>`}</div></div>`).join('')}</section>`).join('')}<section class="syllabus-outcome"><h3>Expected skills</h3><p>${c.outcome}</p><h3>Certificate</h3><p>A Jumi Tech Academy certificate may be issued after successful course completion and full settlement of tuition.</p></section><a class="btn primary" href="/academy/register?course=${encodeURIComponent(c.name)}">Register now →</a></div></div></section>`}
function academyRegister(){return `<section class="pagehero"><div class="container"><span class="eyebrow">ACADEMY ENROLLMENT</span><h1>Choose your course.</h1><p>Review the course timetable and tuition. Register and pay in full, choose installments, or join the waitlist without making a payment.</p></div></section><section class="section"><div class="container academy-layout"><div class="card academy-policy"><span class="eyebrow">Enrollment and payment</span><h2 style="font:700 34px 'Space Grotesk'">Clear steps. Clear fees.</h2><div class="policy-list"><div><strong>Full payment</strong><span>Pay the total course tuition through secure Paystack checkout.</span></div><div><strong>Installments</strong><span>Pay 50% now. The remaining 50% is due one month after classes begin; the Academy will confirm the cohort start date.</span></div><div><strong>Waitlist</strong><span>Register your interest without paying. You will not be charged when joining the waitlist.</span></div><div><strong>Course schedules</strong><span>Review each timetable before choosing multiple courses.</span></div></div><div class="deadline-box"><small>Course tuition</small><strong>₦30,000–₦40,000</strong><span>Frontend, Backend and Python: ₦30,000 each. Ethical Hacking: ₦40,000.</span></div><p class="helper">Registration and payment records are handled by Jumi Tech Academy. A successful Paystack payment must be verified before the payment status is updated.</p></div><div class="card"><form class="form" id="academyForm"><span class="eyebrow">Your details</span><input required name="full_name" autocomplete="name" placeholder="Full name"><input required type="email" name="email" autocomplete="email" placeholder="Email address"><input required type="tel" name="whatsapp" autocomplete="tel" placeholder="WhatsApp phone number"><input required name="location" autocomplete="country-name" placeholder="Country / city"><label><strong>Select course(s) *</strong></label><div class="course-options" id="academyCourses">${Object.entries(academyCourses).map(([slug,c])=>`<label class="course-option"><input type="checkbox" name="courses" value="${c.name}" data-fee="${c.fee}"><span><strong>${c.name}</strong><small>₦${c.fee.toLocaleString('en-NG')} · ${c.schedule}</small></span></label>`).join('')}</div><div class="tuition-estimate" id="tuitionEstimate">Select a course to calculate tuition.</div><label for="paymentPlan"><strong>How would you like to proceed? *</strong></label><select id="paymentPlan" name="payment_plan" required><option value="">Choose an option</option><option value="full">Register and pay in full</option><option value="installments">Register and pay in 2 installments (50% now)</option><option value="waitlist">Join the waitlist — no payment now</option></select><select required name="experience"><option value="">Current skill level</option><option>Complete beginner</option><option>Beginner with some practice</option><option>Intermediate</option><option>Advanced</option></select><select required name="laptop_access"><option value="">Do you have access to a laptop/computer?</option><option>Yes</option><option>No</option><option>Not yet, but planning to get one</option></select><select name="referral_source"><option value="">How did you hear about Jumi Tech Academy? (optional)</option><option>WhatsApp</option><option>Facebook</option><option>Instagram</option><option>TikTok</option><option>Website</option><option>Friend / Referral</option><option>Sales Representative</option><option>Other</option></select><input name="other_course" placeholder="Additional course interest (optional)"><textarea name="goals" placeholder="What would you like to learn or achieve? (optional)"></textarea><button class="btn primary" type="submit" id="academySubmit">Continue →</button><div class="notice" id="academyMsg" role="status" aria-live="polite"></div><p class="notice">By submitting, you agree that Jumi Tech may contact you about your registration. Never send card details or payment PINs to anyone.</p></form></div></div></section>`}
function academyAdmin(){return `<section class="pagehero"><div class="container"><span class="eyebrow">RESTRICTED AREA</span><h1>Academy administration</h1><p>Manage student registrations, payment balances, cohort dates and certificates.</p></div></section><section class="section"><div class="container"><div id="adminLogin" class="card admin-login"><h2>Administrator sign in</h2><form class="form" id="adminLoginForm"><label for="adminPassword">Admin password</label><input id="adminPassword" type="password" autocomplete="current-password" required placeholder="Enter admin password"><button class="btn primary" type="submit">Sign in securely</button><div id="adminLoginMsg" class="notice" role="status"></div></form></div><div id="adminDashboard" hidden><div class="admin-toolbar"><h2>Registrations</h2><div><button class="btn" id="adminRefresh">Refresh</button> <button class="btn" id="adminLogout">Sign out</button></div></div><div id="adminSummary" class="admin-summary"></div><div id="adminRegistrations" class="admin-registration-list"><p>Loading registrations…</p></div><div id="adminMsg" class="notice" role="status"></div></div></div></section>`}
function academyVerify(){return `<section class="pagehero"><div class="container"><span class="eyebrow">CERTIFICATE VERIFICATION</span><h1>Verify a certificate.</h1><p>Enter the unique certificate ID or open this page from the QR code printed on a certificate.</p></div></section><section class="section"><div class="container"><div class="card verify-card"><form id="verifyForm" class="form"><label for="certificateId">Certificate ID</label><input id="certificateId" required placeholder="Example: JT-2026-ABC123"><button class="btn primary" type="submit">Verify certificate</button></form><div id="verifyResult" class="verify-result" role="status" aria-live="polite"></div></div></div></section>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initAcademyRegister(){const form=document.querySelector('#academyForm');if(!form)return;const msg=document.querySelector('#academyMsg');const btn=document.querySelector('#academySubmit');const estimate=document.querySelector('#tuitionEstimate');const params=new URLSearchParams(location.search);const preset=params.get('course');if(preset){const match=[...form.querySelectorAll('input[name="courses"]')].find(x=>x.value===preset);if(match)match.checked=true;}
 const updateEstimate=()=>{const selected=[...form.querySelectorAll('input[name="courses"]:checked')];const total=selected.reduce((s,x)=>s+Number(x.dataset.fee||0),0);const plan=form.payment_plan.value;estimate.innerHTML=total?`<strong>Total tuition: ₦${total.toLocaleString('en-NG')}</strong><span>${plan==='installments'?`Due now: ₦${(total/2).toLocaleString('en-NG')} · Balance: ₦${(total/2).toLocaleString('en-NG')}`:plan==='full'?`Due now: ₦${total.toLocaleString('en-NG')}`:plan==='waitlist'?'No payment is collected to join the waitlist.':'Choose a payment option to see the amount due.'}</span>`:'Select a course to calculate tuition.';};form.addEventListener('change',updateEstimate);updateEstimate();
 const paramsRef=params.get('reference');if(paramsRef){msg.textContent='Verifying your Paystack payment…';fetch('/api/paystack/verify?reference='+encodeURIComponent(paramsRef)).then(r=>r.json()).then(d=>{if(d.status==='success'){const x=d.registration;msg.classList.add('success');msg.innerHTML=`Payment verified. Thank you, ${esc(x.name)}. <br>Courses: ${esc(x.courses.join(', '))}.<br>Paid: ₦${Number(x.amount_paid).toLocaleString('en-NG')} · Balance: ₦${Number(x.balance_due).toLocaleString('en-NG')}.<br>Payment status: ${esc(x.payment_status.replace('_',' '))}. Your registration reference is ${esc(x.id)}.`;}else{msg.classList.add('error');msg.textContent=d.message||'We could not verify this payment yet.';}}).catch(()=>{msg.classList.add('error');msg.textContent='Verification is temporarily unavailable. Keep your payment reference and contact Jumi Tech if needed.';});}
 if(params.get('payment')==='cancelled'){msg.classList.add('error');msg.textContent='Payment was cancelled. Your registration may be saved as pending payment. You can retry by contacting Jumi Tech and providing your registration reference.';}
 form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const selected=[...form.querySelectorAll('input[name="courses"]:checked')].map(x=>x.value);if(!selected.length){msg.classList.add('error');msg.textContent='Please select at least one course.';return;}if(!form.payment_plan.value){msg.classList.add('error');msg.textContent='Choose full payment, installments or waitlist.';return;}btn.disabled=true;btn.textContent='Processing…';msg.classList.remove('error','success');msg.textContent='Saving your registration securely…';const data=Object.fromEntries(new FormData(form).entries());data.courses=selected;try{const r=await fetch('/api/academy/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw new Error(d.message||'Registration could not be completed.');if(d.status==='waitlisted'){form.reset();updateEstimate();msg.classList.add('success');msg.innerHTML=`You have joined the Jumi Tech Academy waitlist. No payment was collected.<br>Reference: ${esc(d.registration_id)}<br>We will contact you with the next steps.`;return;}if(d.authorization_url){msg.textContent='Registration saved. Opening secure Paystack checkout…';location.href=d.authorization_url;return;}throw new Error(d.message||'Registration saved, but checkout could not start.');}catch(err){msg.classList.add('error');msg.textContent=err.message||'Something went wrong. Please try again or contact Jumi Tech.';}finally{btn.disabled=false;btn.textContent='Continue →';}};}
async function initAdmin(){const login=document.querySelector('#adminLogin');const dashboard=document.querySelector('#adminDashboard');const loginForm=document.querySelector('#adminLoginForm');const loginMsg=document.querySelector('#adminLoginMsg');const adminMsg=document.querySelector('#adminMsg');const list=document.querySelector('#adminRegistrations');const summary=document.querySelector('#adminSummary');if(!loginForm)return;let registrations=[];
 const load=async()=>{adminMsg.textContent='Loading registrations…';try{const r=await fetch('/api/admin/registrations');const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to load registrations.');registrations=d.registrations||[];login.hidden=true;dashboard.hidden=false;summary.innerHTML=[['Total registrations',registrations.length],['Waitlisted',registrations.filter(x=>x.registration_status==='waitlisted').length],['Partially paid',registrations.filter(x=>x.payment_status==='partially_paid').length],['Fully paid',registrations.filter(x=>x.payment_status==='paid').length]].map(x=>`<div class="card"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('');list.innerHTML=registrations.length?registrations.map(r=>`<article class="card admin-registration" data-id="${esc(r.id)}"><div class="admin-reg-head"><div><h3>${esc(r.full_name)}</h3><p>${esc(r.email)} · ${esc(r.whatsapp)} · ${esc(r.location)}</p></div><span class="status-pill">${esc(r.payment_status.replace('_',' '))}</span></div><p><strong>Courses:</strong> ${esc((r.courses||[]).join(', '))}</p><p><strong>Tuition:</strong> ₦${Number(r.tuition_total).toLocaleString('en-NG')} · <strong>Paid:</strong> ₦${Number(r.amount_paid).toLocaleString('en-NG')} · <strong>Balance:</strong> ₦${Number(r.balance_due).toLocaleString('en-NG')}</p><p><strong>Registration:</strong> ${esc(r.registration_status)} · <strong>Plan:</strong> ${esc(r.payment_plan)} · <strong>Registered:</strong> ${new Date(r.created_at).toLocaleDateString()}${r.cohort_start_date?` · <strong>Class start:</strong> ${esc(String(r.cohort_start_date).slice(0,10))}`:''}${r.balance_due_date?` · <strong>Balance due:</strong> ${esc(String(r.balance_due_date).slice(0,10))}`:''}</p><p><strong>Payment history:</strong> ${(r.payments||[]).map(p=>`${esc(p.kind)}: ₦${Number(p.amount).toLocaleString('en-NG')} (${esc(p.status)})`).join(' · ')||'No payments yet'}</p><div class="admin-edit-grid"><label>Cohort start date<input type="date" class="cohort-date" value="${esc(r.cohort_start_date||'')}"></label><label>Registration status<select class="reg-status">${['waitlisted','pending_payment','registered','completed','cancelled'].map(s=>`<option value="${s}" ${r.registration_status===s?'selected':''}>${s.replace('_',' ')}</option>`).join('')}</select></label></div><label>Internal notes<textarea class="admin-notes" rows="2">${esc(r.admin_notes||'')}</textarea></label><div class="actions admin-actions"><button class="btn save-reg">Save updates</button>${Number(r.balance_due)>0&&Number(r.amount_paid)>0?'<button class="btn primary balance-link">Create balance payment link</button>':''}${r.payment_status==='paid'&&r.registration_status==='completed'?`<button class="btn certificate-btn">Generate certificate PDF</button>`:''}</div><div class="admin-inline-msg notice"></div></article>`).join(''):'<div class="card"><p>No registrations have been submitted yet.</p></div>';adminMsg.textContent='';bindRows();}catch(e){adminMsg.textContent=e.message;}}
 const bindRows=()=>{list.querySelectorAll('.admin-registration').forEach(card=>{const id=card.dataset.id;const inline=card.querySelector('.admin-inline-msg');card.querySelector('.save-reg').onclick=async()=>{const body={id,cohort_start_date:card.querySelector('.cohort-date').value||null,registration_status:card.querySelector('.reg-status').value,admin_notes:card.querySelector('.admin-notes').value};const r=await fetch('/api/admin/registrations',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();inline.textContent=d.message||'Updated.';if(r.ok)load();};const balance=card.querySelector('.balance-link');if(balance)balance.onclick=async()=>{balance.disabled=true;try{const r=await fetch('/api/admin/balance-payment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({registration_id:id})});const d=await r.json();if(!r.ok)throw new Error(d.message);inline.innerHTML=`Balance payment: <a href="${esc(d.authorization_url)}" target="_blank" rel="noopener">Open checkout</a> · <button type="button" class="copy-balance">Copy link</button>`;inline.querySelector('.copy-balance').onclick=async()=>{await navigator.clipboard.writeText(d.authorization_url);inline.querySelector('.copy-balance').textContent='Copied';};}catch(e){inline.textContent=e.message;}finally{balance.disabled=false;}};const cert=card.querySelector('.certificate-btn');if(cert)cert.onclick=async()=>{const course=prompt('Enter the exact course name to certify:\n'+(registrations.find(x=>x.id===id)?.courses||[]).join('\n'));if(!course)return;const date=prompt('Course completion date (YYYY-MM-DD):',new Date().toISOString().slice(0,10));if(!date)return;cert.disabled=true;try{const r=await fetch('/api/admin/certificate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({registration_id:id,course_name:course,completion_date:date})});if(!r.ok){const d=await r.json();throw new Error(d.message||'Certificate could not be generated.');}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Jumi-Tech-Certificate.pdf';a.click();URL.revokeObjectURL(url);inline.textContent='Certificate PDF generated. Keep the certificate ID printed on the PDF for verification.';}catch(e){inline.textContent=e.message;}finally{cert.disabled=false;}};});};
 loginForm.onsubmit=async e=>{e.preventDefault();loginMsg.textContent='Signing in…';const password=document.querySelector('#adminPassword').value;try{const r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const d=await r.json();if(!r.ok)throw new Error(d.message||'Sign-in failed.');document.querySelector('#adminPassword').value='';await load();}catch(e){loginMsg.textContent=e.message;}};document.querySelector('#adminRefresh').onclick=load;document.querySelector('#adminLogout').onclick=async()=>{await fetch('/api/admin/login',{method:'DELETE'});dashboard.hidden=true;login.hidden=false;loginMsg.textContent='You have signed out.';};const status=await fetch('/api/admin/login');const sd=await status.json();if(sd.authenticated)await load();}
async function initVerify(){const form=document.querySelector('#verifyForm');if(!form)return;const input=document.querySelector('#certificateId');const result=document.querySelector('#verifyResult');const fromUrl=new URLSearchParams(location.search).get('id');if(fromUrl){input.value=fromUrl;verify(fromUrl);}async function verify(id){result.textContent='Checking certificate…';result.className='verify-result';try{const r=await fetch('/api/certificates/verify?id='+encodeURIComponent(id));const d=await r.json();if(!r.ok||!d.valid)throw new Error(d.message||'Certificate could not be verified.');const c=d.certificate;result.classList.add('verified');result.innerHTML=`<span class="eyebrow">Verified certificate</span><h2>Authentic Jumi Tech Academy certificate</h2><dl><dt>Student</dt><dd>${esc(c.student_name)}</dd><dt>Course</dt><dd>${esc(c.course_name)}</dd><dt>Completion date</dt><dd>${esc(String(c.completion_date).slice(0,10))}</dd><dt>Certificate ID</dt><dd>${esc(c.id)}</dd><dt>Issued by</dt><dd>${esc(c.issued_by)}</dd></dl>`;}catch(e){result.classList.add('not-verified');result.textContent=e.message;}}form.onsubmit=e=>{e.preventDefault();verify(input.value.trim());}}
function pageContent(type){const data=pages[location.pathname]||pages['/']; if(type==='home')return home(); if(type==='academy')return academy(); if(type==='academyRegister')return academyRegister(); if(type.startsWith('academyCourse:'))return academyCourse(type.split(':')[1]); if(type==='academyAdmin')return academyAdmin(); if(type==='academyVerify')return academyVerify(); if(type==='about')return `<section class="pagehero"><div class="container"><span class="eyebrow">About Jumi Tech</span><h1>${data.title}</h1><p>${data.intro}</p></div></section><section class="section"><div class="container profile"><div class="portrait reveal"><div><small style="color:var(--cyan)">FOUNDER & LEAD DEVELOPER</small><strong>Michael James</strong><p style="color:var(--muted)">Jumi Tech</p></div></div><div class="card profilebox reveal"><span class="eyebrow">About Me</span><h2 style="font:700 38px 'Space Grotesk'">Building with curiosity. Shipping with purpose.</h2><p>Michael James is the Founder & Lead Developer of Jumi Tech, a technology company focused on turning business ideas into polished digital products.</p><p>His approach blends engineering with product thinking: understand the user, clarify the business objective, design a strong experience, then build technology that can grow with the idea.</p><p>His vision for Jumi Tech is to create a respected African technology company known for exceptional digital products, practical innovation and engineering that creates measurable business value.</p><a class="btn primary" href="/contact">Work with Michael James →</a></div></div></section><section class="section"><div class="container"><div class="sectionhead"><h2>What we believe.</h2><p>Our values shape what we build and how we work.</p></div>${cards([['01','Clarity','Good technology begins with a clear problem and a clear outcome.'],['02','Craft','Details matter — from interface polish to dependable implementation.'],['03','Ownership','We take responsibility for the product, not just the code.'],['04','Useful innovation','New technology matters when it makes something meaningfully better.'],['05','Trust','Direct communication, realistic commitments and professional delivery.'],['06','Growth','We build foundations that can evolve as the business evolves.']])}</div></section>`;
const sets={services:[['01','Website Development','Premium responsive websites built around credibility, conversion and performance.'],['02','Web Applications','Portals, dashboards and workflow applications tailored to your operations.'],['03','SaaS Development','From MVP to scalable subscription products, with product-first thinking.'],['04','UI/UX Design','User journeys, wireframes and high-fidelity interfaces that feel effortless.'],['05','E-commerce Solutions','Commerce experiences designed to make discovery, checkout and management simpler.'],['06','Business Digital Solutions','Digital workflows and systems that reduce friction and improve visibility.'],['07','Custom Software','Purpose-built platforms for specialized business needs.']],solutions:[['01','Customer Experience','Web experiences that make your brand easier to discover, trust and choose.'],['02','Operations','Dashboards and workflow systems that replace scattered manual processes.'],['03','Commerce','Digital storefronts and order journeys designed for conversion.'],['04','Education','Modern school websites and digital platforms for communication and engagement.'],['05','Hospitality','Booking-focused experiences for hotels, resorts and hospitality brands.'],['06','Growth Systems','Landing pages, lead capture and product experiences built around growth.']],products:[['01','Billion Rush','A Jumi Tech-developed Android trivia game featuring a 50-question challenge, timed rounds, lifelines, leaderboards and optional in-game purchases. Prizes are virtual only; there are no real-money payouts.'],['02','Jumi Connect','A digital subscription and data-management concept designed to simplify recurring connectivity needs.'],['03','Jumi Learn AI','An AI-assisted learning product concept focused on accessible, personalized study support.'],['04','Job Application Copilot','A productivity concept helping job seekers organize applications and tailor professional materials.'],['05','Business Tracker','A lightweight sales, customer and debt-tracking product concept for growing businesses.'],['06','Jumi Workspace','A future productivity layer bringing lightweight business workflows into one focused workspace.'],['07','Product Lab','A continuous experimental space for validating ideas before turning the strongest ones into products.']],why:[['01','Business-first','We connect every design and engineering decision to a real business or user outcome.'],['02','Premium by default','We do not treat polish as an afterthought. The experience is part of the product.'],['03','Founder-led','You get direct product and technical ownership rather than layers of unnecessary handoffs.'],['04','Modern foundations','Clean HTML, CSS and JavaScript today; architecture that can evolve tomorrow.'],['05','Mobile-minded','Your customers are everywhere. Every experience is designed to work beautifully on small screens.'],['06','Built to ship','We focus on practical milestones, testable functionality and deployment-ready delivery.']],insights:[['01','Why a website is a business asset','A modern website should answer questions, build trust and create a path to action — not merely display information.'],['02','MVP does not mean mediocre','The smartest MVP is small in scope but strong in experience, positioning and core functionality.'],['03','Design and engineering belong together','When design and implementation collaborate early, products become faster to build and easier to use.'],['04','Choosing custom software','Custom software makes sense when the workflow is important enough that generic tools create costly friction.'],['05','From demo to product','A portfolio demo becomes valuable when it communicates the problem, decisions and outcome behind the interface.'],['06','Building from Africa, thinking globally','Local context can produce globally useful products when engineering quality and product ambition are treated seriously.']],careers:[['01','Frontend Developer','Build polished, accessible interfaces with modern HTML, CSS and JavaScript.'],['02','Product Designer','Shape experiences from user problem through high-fidelity interface.'],['03','Backend Developer','Design APIs, data models and reliable systems behind digital products.'],['04','Growth & Partnerships','Help Jumi Tech connect strong products with businesses that need them.'],['05','Product Intern','Learn by contributing to real product discovery, design and delivery.'],['06','Open application','If you are a thoughtful builder and believe you can create value, tell us what you can do.']]};
if(sets[type])return `<section class="pagehero"><div class="container"><span class="eyebrow">JUMI TECH</span><h1>${data.title}</h1><p>${data.intro}</p></div></section><section class="section"><div class="container">${cards(sets[type])}</div></section><section class="section"><div class="container"><div class="cta"><div><h2>Ready to move forward?</h2><p>Let’s turn your next idea into a credible, useful digital experience.</p></div><a class="btn primary" href="/contact">Talk to Jumi Tech →</a></div></div></section>`;
if(type==='projects')return projects(); if(type==='cases')return cases(); if(type==='process')return process(); if(type==='contact')return contact(); return cards(sets.why)}
function projects(){const ps=[['Game','Billion Rush','A Jumi Tech-developed Android trivia game with 50 questions, timed rounds, lifelines, leaderboards and optional in-game purchases. Virtual prizes only; no real-money payouts.'],['Education','Royal Crest Academy','A polished school website concept focused on trust, admissions and clear communication.'],['Hospitality','Azure Haven Hotel & Suites','A premium hotel experience concept with rooms, experiences, booking-focused journeys and strong conversion points.'],['Restaurant','Spice & Sizzle Food Hub','A vibrant restaurant web experience designed around menu discovery, location and ordering intent.'],['Commerce','E-commerce project','A conversion-minded storefront concept with product discovery and streamlined purchase flows.'],['Platform','Social/Web app','A social product interface concept exploring profiles, feeds and interactive user journeys.'],['SaaS','Business SaaS projects','Dashboard and workflow concepts designed to turn messy business processes into clear digital systems.']];return `<section class="pagehero"><div class="container"><span class="eyebrow">Portfolio</span><h1>${pages['/projects'].title}</h1><p>${pages['/projects'].intro}</p></div></section><section class="section"><div class="container"><div class="filters"><button class="filter active" data-filter="all">All</button>${['Game','Education','Hospitality','Restaurant','Commerce','Platform','SaaS'].map(x=>`<button class="filter" data-filter="${x}">${x}</button>`).join('')}</div><div class="cases">${ps.map((p,i)=>`<article class="case reveal" data-cat="${p[0]}"><small>${p[0]}</small><h3>${p[1]}</h3><p>${p[2]}</p><div style="margin-top:25px"><span class="tag">Strategy</span><span class="tag">Design</span><span class="tag">Development</span></div></article>`).join('')}</div></div></section>`}
function cases(){return `<section class="pagehero"><div class="container"><span class="eyebrow">Case studies</span><h1>${pages['/case-studies'].title}</h1><p>${pages['/case-studies'].intro}</p></div></section><section class="section"><div class="container">${[['Billion Rush','Product Engineering · Mobile Game','Building a mobile trivia experience around a 50-question progression challenge.','Jumi Tech developed Billion Rush as an Android game with timed questions, a prize ladder, three regular lifelines, leaderboards and optional Paystack-powered in-game purchases. The product uses virtual prizes only and does not offer real-money payouts. This case study highlights product design, gameplay flow, payment integration and the work of taking a digital product from concept to a playable release.'],['Royal Crest Academy','Education','A school website concept designed to turn credibility into enquiries.','Clear information architecture, admissions-focused CTAs and a responsive experience built for parents on mobile.'],['Azure Haven Hotel & Suites','Hospitality','A fictional premium hotel brand brought to life as a booking-focused digital experience.','Positioned the hotel around rooms, experiences, trust signals and clear booking intent.'],['Spice & Sizzle Food Hub','Restaurant','A restaurant experience designed to make the next action obvious.','Balanced visual appetite appeal with practical navigation, menu discovery and direct contact paths.']].map(x=>`<article class="card reveal" style="margin-bottom:16px"><small style="color:var(--cyan);font-weight:700">${x[1]}</small><h2 style="font:700 32px 'Space Grotesk'">${x[0]}</h2><h3>${x[2]}</h3><p>${x[3]}</p></article>`).join('')}</div></section>`}
function process(){return `<section class="pagehero"><div class="container"><span class="eyebrow">Our process</span><h1>${pages['/process'].title}</h1><p>${pages['/process'].intro}</p></div></section><section class="section"><div class="container timeline">${[['01','Discover','Understand your users, business model, goals and constraints.'],['02','Define','Turn the problem into a focused product scope, structure and delivery plan.'],['03','Design','Shape the experience, visual system and interaction model before heavy implementation.'],['04','Build','Develop the product with responsive, accessible and maintainable foundations.'],['05','Test','Validate flows, forms, responsiveness and key interactions across devices.'],['06','Launch & improve','Deploy, monitor feedback and identify the highest-value next iteration.']].map(x=>`<div class="step reveal"><b>${x[0]}</b><div><h3 style="margin:0">${x[1]}</h3><p style="color:var(--muted)">${x[2]}</p></div></div>`).join('')}</div></section>`}
function contact(){return `<section class="pagehero"><div class="container"><span class="eyebrow">Contact</span><h1>${pages['/contact'].title}</h1><p>${pages['/contact'].intro}</p></div></section><section class="section"><div class="container feature"><div class="card"><span class="eyebrow">Start a project</span><h2 style="font:700 38px 'Space Grotesk'">Tell us what you’re building.</h2><p>Share enough context for us to understand the goal. We’ll use it to shape a useful first conversation.</p><p style="color:var(--muted)">Email: jumiunlimited@gmail.com<br>WhatsApp: available via the button below</p><a class="btn primary" target="_blank" rel="noopener" href="https://wa.me/2347042536745?text=Hello%20Jumi%20Tech%2C%20I%27d%20like%20to%20discuss%20a%20project.">Chat on WhatsApp →</a></div><div class="card"><form class="form" id="contactForm" action="https://formspree.io/f/xzebazao" method="POST"><input required name="name" autocomplete="name" placeholder="Your name"><input required type="email" name="email" autocomplete="email" placeholder="Email address"><input name="company" autocomplete="organization" placeholder="Company / brand"><select name="service"><option value="">What do you need?</option><option>Website</option><option>Web application</option><option>SaaS product</option><option>UI/UX design</option><option>Custom software</option></select><textarea required name="message" placeholder="Tell us about the project..."></textarea><input type="hidden" name="_subject" value="New Jumi Tech Project Enquiry"><input type="hidden" name="_format" value="plain"><button class="btn primary" type="submit" id="submitBtn">Send project enquiry →</button><div class="notice" id="formMsg" role="status" aria-live="polite"></div></form></div></div></section>`}
function render(){let path=location.pathname;if(path.endsWith('/')&&path!=='/')path=path.slice(0,-1);if(!pages[path])path='/';document.title=(path==='/'?'JUMI TECH — Building Technology That Moves Business Forward.':`JUMI TECH — ${pages[path].title}`);site.innerHTML=common()+pageContent(pages[path].sections)+footer();document.querySelectorAll('.links a').forEach(a=>{if(a.getAttribute('href')===path||(path==='/'&&a.getAttribute('href')==='/'))a.classList.add('active')});document.querySelector('.menu').onclick=()=>document.querySelector('.links').classList.toggle('open');document.querySelectorAll('.reveal').forEach(el=>new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.08}).observe(el));document.querySelectorAll('a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();history.pushState({},'',a.href);render();window.scrollTo(0,0)}));const top=document.querySelector('#top');window.onscroll=()=>top.style.display=scrollY>500?'block':'none';top.onclick=()=>scrollTo({top:0,behavior:'smooth'});if(path==='/projects'){document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.case').forEach(c=>c.style.display=b.dataset.filter==='all'||c.dataset.filter===b.dataset.filter?'block':'none')})}if(path==='/academy/register')initAcademyRegister();if(path==='/academy/admin')initAdmin();if(path==='/academy/verify')initVerify();if(path==='/contact'){const form=document.querySelector('#contactForm');const msg=document.querySelector('#formMsg');const btn=document.querySelector('#submitBtn');form.onsubmit=async e=>{e.preventDefault();if(!form.checkValidity()){form.reportValidity();return}if(!form.action.includes('formspree.io/f/xzebazao')){msg.textContent='Formspree endpoint is not configured correctly. Please verify the form action.';msg.classList.add('error');return}btn.disabled=true;btn.textContent='Sending enquiry…';msg.classList.remove('error');try{const res=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});if(res.ok){form.reset();msg.textContent='Thank you. Your project enquiry has been sent successfully. We’ll be in touch soon.';msg.classList.add('success')}else{const data=await res.json().catch(()=>({}));msg.textContent=data.errors?.map(x=>x.message).join(' ')||'We could not send your enquiry. Please try again or contact Jumi Tech on WhatsApp.';msg.classList.add('error')}}catch(err){msg.textContent='Network error. Please check your connection or contact Jumi Tech on WhatsApp.';msg.classList.add('error')}finally{btn.disabled=false;btn.textContent='Send project enquiry →'}}}}
window.onpopstate=render;render();
